package com.peertutoring.ui;

import com.peertutoring.model.Student;import com.peertutoring.model.Subject;import com.peertutoring.model.TutoringSession;import com.peertutoring.service.SessionService;import com.peertutoring.service.TutorService;
import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.SQLException;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.HashMap;import java.util.List;import java.util.Map;

public class SessionRequestsFrame extends JFrame {
 private final Student student;private final SessionService sessions=new SessionService();private final TutorService tutors=new TutorService();private final Map<Integer,String> subjectNames=new HashMap<>();private final DefaultTableModel learnerModel=createModel(),tutorModel=createModel();private final JTable learnerTable=new JTable(learnerModel),tutorTable=new JTable(tutorModel);private final DateTimeFormatter fmt=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
 public SessionRequestsFrame(Student student){this.student=student;setTitle("PeerTutoringSystems | Session Requests");setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);setSize(1000,590);setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(10,12));root.setBackground(new Color(245,247,251));root.setBorder(new EmptyBorder(22,24,22,24));JLabel title=new JLabel("Tutoring sessions");title.setFont(new Font("SansSerif",Font.BOLD,25));root.add(title,BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Requests I made",makeTab(learnerTable,false));tabs.addTab("Requests I received",makeTab(tutorTable,true));root.add(tabs,BorderLayout.CENTER);setContentPane(root);loadSubjects();refresh();}
 private DefaultTableModel createModel(){return new DefaultTableModel(new String[]{"Session ID","Subject","Other student ID","Requested at","Scheduled at","Message","Status"},0){public boolean isCellEditable(int r,int c){return false;}};}
 private JPanel makeTab(JTable table,boolean asTutor){table.setRowHeight(27);table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);int[] widths={80,150,120,150,150,220,100};for(int i=0;i<widths.length;i++)table.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);JPanel p=new JPanel(new BorderLayout(8,8));p.add(new JScrollPane(table),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton refresh=new JButton("Refresh");refresh.addActionListener(e->refresh());actions.add(refresh);if(asTutor){JButton accept=new JButton("Accept"),reject=new JButton("Reject"),complete=new JButton("Mark completed");accept.addActionListener(e->change(tutorTable,true,"ACCEPT"));reject.addActionListener(e->change(tutorTable,true,"REJECT"));complete.addActionListener(e->change(tutorTable,true,"COMPLETE"));actions.add(accept);actions.add(reject);actions.add(complete);}else{JButton cancel=new JButton("Cancel pending request");cancel.addActionListener(e->change(learnerTable,false,"CANCEL"));actions.add(cancel);}p.add(actions,BorderLayout.SOUTH);return p;}
 private void loadSubjects(){try{for(Subject s:tutors.getAllSubjects())subjectNames.put(s.getSubjectId(),s.getSubjectName());}catch(SQLException ex){dbError();}}
 private void refresh(){try{learnerModel.setRowCount(0);tutorModel.setRowCount(0);for(TutoringSession s:sessions.getLearnerSessions(student.getStudentId()))addRow(learnerModel,s,false);for(TutoringSession s:sessions.getTutorSessions(student.getStudentId()))addRow(tutorModel,s,true);}catch(SQLException ex){dbError();}}
 private void addRow(DefaultTableModel m,TutoringSession s,boolean tutorView){int other=tutorView?s.getLearnerId():s.getTutorId();m.addRow(new Object[]{s.getSessionId(),subjectNames.getOrDefault(s.getSubjectId(),"Subject #"+s.getSubjectId()),other,format(s.getRequestedAt()),format(s.getScheduledAt()),s.getMessage()==null?"":s.getMessage(),s.getStatus()});}
 private String format(LocalDateTime t){return t==null?"Not scheduled":t.format(fmt);}
 private void change(JTable table,boolean asTutor,String action){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a session first.");return;}int id=(Integer)table.getValueAt(row,0);String status=String.valueOf(table.getValueAt(row,6));boolean allowed=switch(action){case "ACCEPT","REJECT","CANCEL"->"PENDING".equalsIgnoreCase(status);case "COMPLETE"->"ACCEPTED".equalsIgnoreCase(status);default->false;};if(!allowed){JOptionPane.showMessageDialog(this,"This action is not available for the session's current status.");return;}int confirm=JOptionPane.showConfirmDialog(this,"Confirm action: "+action.toLowerCase()+"?","Confirm session update",JOptionPane.YES_NO_OPTION);if(confirm!=JOptionPane.YES_OPTION)return;try{boolean ok=switch(action){case "ACCEPT"->sessions.acceptRequest(id,student.getStudentId());case "REJECT"->sessions.rejectRequest(id,student.getStudentId());case "COMPLETE"->sessions.completeSession(id,student.getStudentId());case "CANCEL"->sessions.cancelRequest(id,student.getStudentId());default->false;};if(ok)JOptionPane.showMessageDialog(this,"Session updated successfully.","Success",JOptionPane.INFORMATION_MESSAGE);else JOptionPane.showMessageDialog(this,"No update was made. The session may have changed already.","Update unsuccessful",JOptionPane.WARNING_MESSAGE);refresh();}catch(SQLException ex){dbError();}catch(IllegalArgumentException ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Update failed",JOptionPane.WARNING_MESSAGE);}}
 private void dbError(){JOptionPane.showMessageDialog(this,"Unable to load or update sessions. Check the database connection.","Database error",JOptionPane.ERROR_MESSAGE);}
}
